<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('pelamar');$s=$pdo->prepare('SELECT la.*,l.judul_lowongan,d.nama_divisi,ts.nama_tahapan FROM lamaran la JOIN lowongan l ON l.id_lowongan=la.id_lowongan JOIN divisi d ON d.id_divisi=l.id_divisi LEFT JOIN tahapan_seleksi ts ON ts.id_tahapan=la.id_tahapan_aktif WHERE la.id_pelamar=? ORDER BY la.id_lamaran DESC');$s->execute([user()['id_pelamar']]);$rows=$s->fetchAll();page_header('Dashboard Pelamar');?><div class="card"><a class="btn" href="lowongan.php">Lihat Lowongan Aktif</a></div><table><tr><th>Posisi</th><th>Divisi</th><th>Tahap</th><th>Status</th><th>Tanggal</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['judul_lowongan'])?></td><td><?=e($r['nama_divisi'])?></td><td><?=e($r['nama_tahapan']?:'Selesai')?></td><td><?=e($r['status_lamaran'])?></td><td><?=e($r['tanggal_lamar'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">Belum ada lamaran.</td></tr><?php endif;?></table><?php page_footer();
